import{_ as l,o as a,c as i,a5 as o}from"./chunks/framework.BF53ZjCA.js";const u=JSON.parse('{"title":"GemAtlas 欧珀首页 Hero 设计规范","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-09-07-opal-homepage-hero-design.md","filePath":"superpowers/specs/2026-09-07-opal-homepage-hero-design.md","lastUpdated":1789155237000}'),t={name:"superpowers/specs/2026-09-07-opal-homepage-hero-design.md"};function d(r,e,c,h,n,s){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="gematlas-欧珀首页-hero-设计规范" tabindex="-1">GemAtlas 欧珀首页 Hero 设计规范 <a class="header-anchor" href="#gematlas-欧珀首页-hero-设计规范" aria-label="Permalink to &quot;GemAtlas 欧珀首页 Hero 设计规范&quot;">​</a></h1><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><ul><li>状态：实现完成，等待用户体验复核。</li><li>日期：2026-09-07</li><li>范围：独立首页 Hero 与进入知识百科主页的入口体验。</li><li>当前项目约束：GemAtlas 当前使用 VitePress + Vue 3 + TypeScript，不迁移到 React/Tailwind/shadcn。</li></ul><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>把首页第一屏做成“从一束光，认识一颗宝石”的沉浸式入口：访客先看到暗场中的欧珀成品，再看到全屏光线缓慢扫过，欧珀变彩逐渐显现，最后通过顶部模块入口进入五个知识板块。</p><p>首页 Hero 负责建立视觉记忆和学习动机，不在第一屏塞入完整科普内容；欧珀的成因、变彩原理、切割与鉴定细节继续由现有知识页面承载。</p><h2 id="已确认的视觉方向" tabindex="-1">已确认的视觉方向 <a class="header-anchor" href="#已确认的视觉方向" aria-label="Permalink to &quot;已确认的视觉方向&quot;">​</a></h2><h3 id="主体素材" tabindex="-1">主体素材 <a class="header-anchor" href="#主体素材" aria-label="Permalink to &quot;主体素材&quot;">​</a></h3><p>采用 A 方向的叙事骨架：展柜正面、欧珀成品微距、主体占据主要视觉重量。候选素材为 Wikimedia Commons 的 Rainbow Shield 欧珀吊坠照片（2807×3358，作者 Dpulitzer，CC BY-SA 4.0）。正式纳入仓库前必须下载本地副本、核对文件页信息，并在 <code>docs/image-credits.md</code> 中记录作者、来源、许可和本地处理方式。</p><p>素材处理原则：</p><ul><li>优先保留欧珀、金属镶嵌和真实反光，不使用生成式宝石替换真实主体。</li><li>采用微距裁切和轻微镜头推进，让成品进入画面主体，而不是固定在底部作为装饰。</li><li>裁切必须保留标题安全区和欧珀轮廓；桌面、展签等背景信息不作为 Hero 的主要叙事。</li><li>如果素材无法同时满足清晰度、构图和开源许可，保留素材候选但不纳入正式首页，等待更合适的授权照片或视频。</li></ul><h3 id="版式" tabindex="-1">版式 <a class="header-anchor" href="#版式" aria-label="Permalink to &quot;版式&quot;">​</a></h3><ul><li>全屏深色展柜舞台，首页根节点至少占满 <code>100svh</code>，兼容移动端地址栏变化。</li><li>标题始终位于视觉中心：<code>从一束光，认识</code> / <code>一颗宝石。</code>。</li><li>视觉层级保持克制：中央标题为唯一主叙事锚点，欧珀成品右侧偏置并通过边缘淡出避免侵入标题安全区。</li><li>成品以微距比例从暗场中显现，初始位置接近中心视觉轴；不使用“底部孤立悬浮宝石”构图。</li><li>标题与成品之间保留暗部安全区，用构图和低强度暗部渐变保障可读性，不使用厚重遮罩压平素材。</li><li>顶部为一组玻璃胶囊模块跳转键：<code>01 分类</code>、<code>02 鉴定</code>、<code>03 切割</code>、<code>04 分级</code>、<code>05 画廊</code>。当前模块高亮，键面具有清晰的 hover、focus-visible 和 active 状态。</li><li>移动端允许模块胶囊横向滚动，但每个入口触控区域不小于 44×44px；不依赖 hover 才能发现入口。</li></ul><h3 id="文案" tabindex="-1">文案 <a class="header-anchor" href="#文案" aria-label="Permalink to &quot;文案&quot;">​</a></h3><ul><li>主标题：<code>从一束光，认识一颗宝石。</code></li><li>辅助文案：<code>光线掠过欧珀的微小结构，沉睡的色彩开始显现。进入 GemAtlas，从看见开始学习。</code></li><li>Hero 行动入口：进入知识百科主页；按钮文案可使用 <code>开始探索</code>。</li><li>事实型说明不在 Hero 中夸大：变彩动画是对光线揭示过程的视觉化表达，不宣称照片中的欧珀在现实中自行变色。</li></ul><h2 id="动效时间线" tabindex="-1">动效时间线 <a class="header-anchor" href="#动效时间线" aria-label="Permalink to &quot;动效时间线&quot;">​</a></h2><p>动效目的为“解释”和“避免突兀切换”，不是持续刺激。媒体本身承担主要运动，UI 只做必要的状态反馈。</p><p>总循环约 14 秒：</p><table tabindex="0"><thead><tr><th>时间</th><th>状态</th><th>视觉行为</th></tr></thead><tbody><tr><td>0–2 秒</td><td>暗场建立</td><td>成品保持低亮度，仅保留轮廓和极弱环境反光；标题保持可读。</td></tr><tr><td>2–9 秒</td><td>光线揭示</td><td>光线以匀速、低对比度从全屏暗部缓慢扫过；经过欧珀区域时，变彩从局部逐步扩展。使用 <code>linear</code> 控制扫描，不在中段突然加速。</td></tr><tr><td>9–14 秒</td><td>色彩停留</td><td>保留最完整的变彩和金属反光约 5 秒，再回到循环起点。</td></tr></tbody></table><p>实现选择：首版优先使用 CSS animation + <code>transform</code> / <code>opacity</code> / <code>clip-path</code>，配合本地真实照片实现镜头推进、光线扫掠和色彩显现；不为这一段引入动画库。若之后取得合适的真实欧珀转动视频，视频仅替换媒体层，保留同一套标题、导航和可访问性接口。</p><p>动效约束：</p><ul><li>光束覆盖全屏，不固定为左侧单根竖线。</li><li>光束速度恒定；亮度和颜色的变化可以缓慢淡入，但不能使用中段加速制造闪烁。</li><li>镜头推进幅度很小，只用于空间连续性，不让主体离开标题安全区。</li><li><code>prefers-reduced-motion: reduce</code> 下停留在清晰的静态最终画面，保留颜色和对比度，不执行推进、扫掠和循环。</li><li>不提供额外的重播按钮；普通动效设备进入页面后自动循环，减弱动效设备改为不移动位置的低对比度亮度/色彩呼吸循环。</li><li>所有 hover 动效只在支持精确指针的设备启用；焦点状态必须立即可见。</li></ul><h2 id="页面结构与导航" tabindex="-1">页面结构与导航 <a class="header-anchor" href="#页面结构与导航" aria-label="Permalink to &quot;页面结构与导航&quot;">​</a></h2><p>新增独立首页作为站点根入口：</p><ol><li>根首页展示欧珀 Hero。</li><li>Hero 的主行动入口进入独立知识百科入口 <code>/zh/compendium/</code>；英文入口进入 <code>/compendium/</code>，避免与沉浸式 Hero 首页形成回跳。</li><li>顶部五个模块键复用现有模块路由，不复制模块内容，也不在 Hero 内嵌第二套导航数据。</li><li>原有知识入口内容保留在独立百科页，避免用户从入口动效直接失去已有内容。</li></ol><p>组件职责建议：</p><ul><li><code>GemAtlasLanding.vue</code>：页面结构、Hero 文案、入口跳转和 reduced-motion 状态。</li><li><code>OpalRevealMedia.vue</code>：素材加载、poster/fallback、光束与变彩揭示层、时间线。</li><li><code>ModuleJumpNav.vue</code>：五个模块入口、当前状态、键盘焦点和移动端横向滚动。</li></ul><p>组件之间只通过明确的 props / links 传递素材和路由，不新增全局状态管理。</p><h2 id="加载、失败与性能" tabindex="-1">加载、失败与性能 <a class="header-anchor" href="#加载、失败与性能" aria-label="Permalink to &quot;加载、失败与性能&quot;">​</a></h2><ul><li>正式素材必须本地化，避免首页依赖第三方 CDN 运行。</li><li>为首屏图片预留固定容器比例，避免图片加载造成布局位移。</li><li>图片加载失败时显示深色展柜背景、标题和可用的“进入知识百科”按钮；不得出现破碎图片图标作为唯一内容。</li><li>如果未来使用视频，必须提供本地 poster、<code>muted</code>、<code>playsInline</code>、循环控制，并在移动端和 reduced-motion 模式下允许只显示 poster。</li><li>首屏只加载一套主媒体，不同时预加载多个候选素材。</li><li>动效只改变合成友好的属性；避免动画驱动布局尺寸、页面滚动或高频 JS 定时器。</li></ul><h2 id="无障碍与交互验收" tabindex="-1">无障碍与交互验收 <a class="header-anchor" href="#无障碍与交互验收" aria-label="Permalink to &quot;无障碍与交互验收&quot;">​</a></h2><ul><li>标题、辅助文案、导航和主入口在键盘顺序中可访问。</li><li>五个模块入口为真实链接，拥有清晰的可见焦点环和当前状态，不仅依赖颜色区分。</li><li>图片 alt 说明真实主体；装饰性的光束和色彩层标记为隐藏。</li><li>文字与背景满足至少 4.5:1 的普通文本对比度；中央标题在最亮变彩状态仍可读。</li><li>触控目标至少 44×44px，移动端无横向页面溢出。</li><li><code>prefers-reduced-motion</code>、图片失败和慢速网络都能得到可用的静态体验。</li></ul><h2 id="验收标准" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准" aria-label="Permalink to &quot;验收标准&quot;">​</a></h2><h3 id="视觉" tabindex="-1">视觉 <a class="header-anchor" href="#视觉" aria-label="Permalink to &quot;视觉&quot;">​</a></h3><ul><li>第一眼主体是欧珀成品，不是背景图片或装饰光束。</li><li>标题始终处于屏幕中央且不被主体高亮区域破坏可读性。</li><li>光线在约 15 秒内匀速扫过全屏，变彩缓慢显现并停留约 5 秒。</li><li>顶部五个模块入口完整显示，编号连续为 01–05，且具有明确 active/focus 状态。</li><li>桌面端、窄屏移动端均无裁切到无法识别主体或无法点击入口的情况。</li></ul><h3 id="工程" tabindex="-1">工程 <a class="header-anchor" href="#工程" aria-label="Permalink to &quot;工程&quot;">​</a></h3><ul><li><code>pnpm validate:data</code> 通过。</li><li><code>pnpm generate:pages</code> 通过且不产生非预期页面差异。</li><li><code>pnpm test</code> 通过。</li><li><code>pnpm build</code> 通过。</li><li>生产页面不依赖未经记录许可的外部图片或视频。</li><li>至少完成一次真实浏览器检查：首屏加载、五个模块跳转、主入口跳转、键盘焦点、图片失败 fallback 和 reduced-motion。</li></ul><h2 id="不在本次实现范围" tabindex="-1">不在本次实现范围 <a class="header-anchor" href="#不在本次实现范围" aria-label="Permalink to &quot;不在本次实现范围&quot;">​</a></h2><ul><li>将整个 VitePress 项目迁移为 React + Tailwind + shadcn。</li><li>在 Hero 内完成欧珀成因、鉴定、切割和分级的完整教学。</li><li>生成或伪造欧珀内部结构的科学动画。</li><li>未经授权直接使用商业珠宝品牌或电商素材。</li><li>同时制作多个独立首页版本并引入复杂实验框架。</li></ul><h2 id="素材与科学依据" tabindex="-1">素材与科学依据 <a class="header-anchor" href="#素材与科学依据" aria-label="Permalink to &quot;素材与科学依据&quot;">​</a></h2><ul><li>欧珀成品候选：<a href="https://commons.wikimedia.org/wiki/File:Rainbow_Shield_Opal_Pendant_Jewelry.jpg" target="_blank" rel="noreferrer">Rainbow Shield Opal Pendant Jewelry</a>，作者 Dpulitzer，CC BY-SA 4.0；正式使用时保留署名并遵守 ShareAlike 条款。</li><li>欧珀变彩原理：<a href="https://www.gia.edu/opal-description" target="_blank" rel="noreferrer">GIA Opal Description</a>。Hero 动效只做可视化叙事，科学解释仍以知识页面和可靠资料为准。</li></ul>',41)])])}const m=l(t,[["render",d]]);export{u as __pageData,m as default};
